def render(data: dict) -> str:
    cards = ''.join(
        f'<article class="x146-depth__card"><h3>{title}</h3><p>{text}</p></article>'
        for title, text in data['cards']
    )
    links = ''.join(
        f'<a href="{href}">{label}</a>' for href, label in data['links']
    )
    return (
        '<section class="x146-depth" data-stage146-search-depth="true" aria-labelledby="x146-depth-title">'
        '<div class="x146-depth__inner">'
        '<div class="x146-depth__head">'
        f'<p class="x146-depth__eyebrow">{data["eyebrow"]}</p>'
        '<div>'
        f'<h2 id="x146-depth-title">{data["title"]}</h2>'
        f'<p class="x146-depth__intro">{data["intro"]}</p>'
        '</div></div>'
        f'<div class="x146-depth__grid">{cards}</div>'
        f'<nav class="x146-depth__links" aria-label="Связанные материалы">{links}</nav>'
        '</div></section>'
    )


changed = []
for rel, data in PAGES.items():
    path = ROOT / rel
    if not path.is_file():
        raise SystemExit(f'stage146: missing {rel}')
    html = path.read_text(encoding='utf-8')
    html = re.sub(
        r'\s*<section\b[^>]*data-stage146-search-depth="true"[^>]*>.*?</section>\s*',
        '\n',
        html,
        count=1,
        flags=re.I | re.S,
    )
    block = render(data)
    markers = ('<section class="contact"', '<section class="p129-contact"', '</main>')
    marker = next((m for m in markers if m in html), None)
    if marker is None:
        raise SystemExit(f'stage146: insertion marker missing in {rel}')
    html = html.replace(marker, block + '\n' + marker, 1)
    path.write_text(html, encoding='utf-8')
    changed.append(rel)

if len(changed) != len(PAGES):
    raise SystemExit(f'stage146: expected {len(PAGES)} pages, got {len(changed)}')

print('stage146 search depth: enriched ' + ', '.join(changed))
